import { Observable, from, map } from './observable';

test('subscribe receives next values', () => {
  const received: number[] = [];
  const obs = new Observable<number>((observer) => {
    observer.next(1);
    observer.next(2);
    observer.next(3);
  });
  obs.subscribe({ next: (v) => received.push(v) });
  expect(received).toEqual([1, 2, 3]);
});

test('complete is called', () => {
  let done = false;
  const obs = new Observable<number>((observer) => {
    observer.next(1);
    observer.complete();
  });
  obs.subscribe({ complete: () => { done = true; } });
  expect(done).toBe(true);
});

test('error is called', () => {
  let caught: unknown = null;
  const obs = new Observable<number>((observer) => {
    observer.error(new Error('oops'));
  });
  obs.subscribe({ error: (e) => { caught = e; } });
  expect(caught).toBeInstanceOf(Error);
});

test('unsubscribe stops future emissions', () => {
  const received: number[] = [];
  let emitter: ((v: number) => void) | null = null;
  const obs = new Observable<number>((observer) => {
    emitter = (v) => observer.next(v);
  });
  const sub = obs.subscribe({ next: (v) => received.push(v) });
  emitter!(1);
  sub.unsubscribe();
  emitter!(2); // should not reach observer after unsubscribe
  expect(received).toEqual([1]);
});

test('from emits array values', () => {
  const received: number[] = [];
  from([10, 20, 30]).subscribe({ next: (v) => received.push(v) });
  expect(received).toEqual([10, 20, 30]);
});

test('map transforms values', () => {
  const received: string[] = [];
  from([1, 2, 3]).pipe(map((v) => `item-${v}`)).subscribe({ next: (v) => received.push(v) });
  expect(received).toEqual(['item-1', 'item-2', 'item-3']);
});
